    const AB = (() => { let s = ''; for (let c = 40; c <= 126; c++) if (c !== 92) s += String.fromCharCode(c); return s; })();
    const IX = new Uint8Array(128); for (let i = 0; i < AB.length; i++) IX[AB.charCodeAt(i)] = i;
    const unrle = (str, n) => { const o = new Uint8Array(n); let p = 0; for (let i = 0; i < str.length; i += 2) { const v = IX[str.charCodeAt(i)], k = IX[str.charCodeAt(i + 1)] + 1; o.fill(v, p, p + k); p += k; } return o; };
